public String[] dissect(String path) {
    char sep = File.separatorChar;
    path = path.replace('/', sep).replace('\\', sep);

    // make sure we are dealing with an absolute path
    if (!isAbsolutePath(path)) {
        throw new BuildException(path + " is not an absolute path");
    }

    String root;
    int colon = path.indexOf(':');
    if (colon > 0 && (ON_DOS || ON_NETWARE)) {
        root = constructRootForDosOrNetware(path, colon, sep);
        path = removeInitialSeparator(path, sep);
    } else if (path.length() > 1 && path.charAt(1) == sep) {
        // UNC drive
        int nextsep = path.indexOf(sep, 2);
        nextsep = path.indexOf(sep, nextsep + 1);
        root = (nextsep > 2) ? path.substring(0, nextsep + 1) : path;
        path = path.substring(root.length());
    } else {
        root = File.separator;
        path = path.substring(1);
    }

    return new String[] {root, path};
}

private String constructRootForDosOrNetware(String path, int colon, char sep) {
    String root = path.substring(0, colon + 1);
    root += sep;
    return root;
}

private String removeInitialSeparator(String path, char sep) {
    char[] ca = path.toCharArray();
    int next = (ca[colon + 1] == sep) ? colon + 2 : colon + 1;
    StringBuffer sbPath = new StringBuffer();
    for (int i = next; i < ca.length; i++) {
        if (ca[i] != sep || ca[i - 1] != sep) {
            sbPath.append(ca[i]);
        }
    }
    return sbPath.toString();
}

