/**
 * Retrieves the Class-Path attribute from the manifest of a JAR file,
 * caching the result based on file path, last modified time, and size.
 *
 * @param pathComponent the JAR file to inspect
 * @return the manifest's Class-Path value, or empty string if none
 * @throws IOException if the manifest cannot be read
 */
private String getManifestClasspath(File pathComponent) throws IOException {
    String key = pathComponent.getAbsolutePath()
            + pathComponent.lastModified() + "-" + pathComponent.length();
    String classpath = (String) pathMap.get(key);
    if (classpath == null) {
        JarFile jarFile = null;
        try {
            jarFile = new JarFile(pathComponent);
            Manifest manifest = jarFile.getManifest();
            if (manifest == null) {
                return "";
            }
            classpath = manifest.getMainAttributes()
                .getValue(Attributes.Name.CLASS_PATH);
        } finally {
            if (jarFile != null) {
                jarFile.close();
            }
        }
        if (classpath == null) {
            classpath = "";
        }
        pathMap.put(key, classpath);
    }
    return classpath;
}

/**
 * Processes each classpath entry from the manifest, resolving and adding
 * referenced JARs as path components.
 *
 * @param pathComponent the original JAR file
 * @param classpath the manifest Class-Path value
 * @throws IOException if URL resolution or file access fails
 */
private void processManifestClasspath(File pathComponent, String classpath) throws IOException {
    URL baseURL = FILE_UTILS.getFileURL(pathComponent);
    StringTokenizer st = new StringTokenizer(classpath);
    while (st.hasMoreTokens()) {
        String classpathElement = st.nextToken();
        URL libraryURL = new URL(baseURL, classpathElement);
        if (!libraryURL.getProtocol().equals("file")) {
            log("Skipping jar library " + classpathElement
                    + " since only relative URLs are supported by this" + " loader",
                    Project.MSG_VERBOSE);
            continue;
        }
        String decodedPath = Locator.decodeUri(libraryURL.getFile());
        File libraryFile = new File(decodedPath);
        if (libraryFile.exists() && !isInPath(libraryFile)) {
            addPathFile(libraryFile);
        }
    }
}

