private String getAltCompilerName(String anImplementation) {
    String strippedImpl = stripJdkPrefix(anImplementation);
    String assumed = assumedJavaVersion();

    if (MODERN.equalsIgnoreCase(strippedImpl) || CLASSIC.equalsIgnoreCase(strippedImpl)
            || EXTJAVAC.equalsIgnoreCase(strippedImpl)) {
        return assumed;
    }
    if (isModernVariant(strippedImpl)) {
        return MODERN;
    }
    if (isClassicVariant(strippedImpl)) {
        return CLASSIC;
    }
    return null;
}

/**
 * Removesjdk javac prefix (javac1.x) from the given compiler implementation name.
 */
private String stripJdkPrefix(String impl) {
    if (impl == null) {
        return null;
    }
    String lower = impl.toLowerCase();
    if (lower.startsWith("javac1.")) {
        return MODERN;
    }
    if (lower.equals("javac1.1") || lower.equals("javac1.2")) {
        return impl;
    }
    return impl;
}

/**
 * Returns true if the given compiler implementation is a modern JDK compiler variant.
 */
private boolean isModernVariant(String impl) {
    String lower = impl.toLowerCase();
    return JAVAC17.equalsIgnoreCase(lower)
            || JAVAC18.equalsIgnoreCase(lower)
            || JAVAC16.equalsIgnoreCase(lower)
            || JAVAC15.equalsIgnoreCase(lower)
            || JAVAC14.equalsIgnoreCase(lower)
            || JAVAC13.equalsIgnoreCase(lower);
}

/**
 * Returns true if the given compiler implementation is a classic JDK compiler variant.
 */
private boolean isClassicVariant(String impl) {
    String lower = impl.toLowerCase();
    return JAVAC12.equalsIgnoreCase(lower)
            || JAVAC11.equalsIgnoreCase(lower);
}

private String getAltCompilerName(String anImplementation) {
    if (isModernish(anImplementation)) {
        return MODERN;
    }
    if (isClassicish(anImplementation)) {
        return CLASSIC;
    }
    if (MODERN.equalsIgnoreCase(anImplementation)) {
        String next = assumedJavaVersion();
        if (isModernish(next)) {
            return next;
        }
    }
    if (CLASSIC.equalsIgnoreCase(anImplementation)) {
        return assumedJavaVersion();
    }
    if (EXTJAVAC.equalsIgnoreCase(anImplementation)) {
        return assumedJavaVersion();
    }
    return null;
}

private boolean isModernish(String impl) {
    return JAVAC17.equalsIgnoreCase(impl)
        || JAVAC18.equalsIgnoreCase(impl)
        || JAVAC16.equalsIgnoreCase(impl)
        || JAVAC15.equalsIgnoreCase(impl)
        || JAVAC14.equalsIgnoreCase(impl)
        || JAVAC13.equalsIgnoreCase(impl);
}

private boolean isClassicish(String impl) {
    return JAVAC12.equalsIgnoreCase(impl)
        || JAVAC11.equalsIgnoreCase(impl);
}

