            } else if (arg.equals("-listener")) {
                i = handleArgListener(args, i);
            } else if (arg.startsWith("-D")) {
                i = handleArgDefine(args, i);
            } else if (arg.equals("-logger")) {
                i = handleArgLogger(args, i);
            } else if (arg.equals("-inputhandler")) {
                i = handleArgInputHandler(args, i);
            } else if (isEmacsArgument(arg)) {
                emacsMode = true;
            } else if (isProjectHelpArgument(arg)) {
                projectHelp = true;
            } else if (isFindArgument(arg)) {
                searchForFile = true;
                if (i < args.length - 1) {
                    searchForThis = args[++i];
                }
            } else if (arg.startsWith("-propertyfile")) {
                i = handleArgPropertyFile(args, i);
            } else if (isKeepGoingArgument(arg)) {
                keepGoingMode = true;
            } else if (arg.equals("-nice")) {
                i = handleArgNice(args, i);
            } else if (LAUNCH_COMMANDS.contains(arg)) {
                String msg = "Ant's Main method is being handed "
                        + "an option " + arg + " that is only for the launcher class."
                        + "\nThis can be caused by a version mismatch between "
                        + "the ant script/.bat file and Ant itself.";
                throw new BuildException(msg);
            } else if (arg.equals("-autoproxy")) {
                proxy = true;
            } else if (arg.startsWith("-")) {
                i = processCustomArgument(args, i, arg, processorRegistry);
            } else {
                targets.addElement(arg);
            }
        }

        if (msgOutputLevel >= Project.MSG_VERBOSE || justPrintVersion) {
            printVersion(msgOutputLevel);
        }

        if (justPrintUsage || justPrintVersion || justPrintDiagnostics) {
            if (justPrintUsage) {
                printUsage();
            }
            if (justPrintDiagnostics) {
                Diagnostics.doReport(System.out, msgOutputLevel);
            }
            return;
        }

        processBuildFile(searchForFile, searchForThis);

        if (logTo != null) {
            out = logTo;
            err = logTo;
            System.setOut(out);
            System.setErr(err);
        }
        readyToRun = true;
    }

    private boolean isHelpArgument(String arg) {
        return arg.equals("-help") || arg.equals("-h");
    }

    private boolean isQuietArgument(String arg) {
        return arg.equals("-quiet") || arg.equals("-q");
    }

    private boolean isVerboseArgument(String arg) {
        return arg.equals("-verbose") || arg.equals("-v");
    }

    private boolean isDebugArgument(String arg) {
        return arg.equals("-debug") || arg.equals("-d");
    }

    private boolean isSilentArgument(String arg) {
        return arg.equals("-silent") || arg.equals("-S");
    }

    private boolean isLogfileArgument(String arg) {
        return arg.equals("-logfile") || arg.equals("-l");
    }

    private boolean isBuildfileArgument(String arg) {
        return arg.equals("-buildfile") || arg.equals("-file") || arg.equals("-f");
    }

    private boolean isEmacsArgument(String arg) {
        return arg.equals("-emacs") || arg.equals("-e");
    }

    private boolean isProjectHelpArgument(String arg) {
        return arg.equals("-projecthelp") || arg.equals("-p");
    }

    private boolean isFindArgument(String arg) {
        return arg.equals("-find") || arg.equals("-s");
    }

    private boolean isKeepGoingArgument(String arg) {
        return arg.equals("-k") || arg.equals("-keep-going");
    }

    private int processLogfileArgument(String[] args, int i, PrintStream logTo) {
        try {
            File logFile = new File(args[i + 1]);
            i++;
            PrintStream newLogTo = new PrintStream(new FileOutputStream(logFile));
            isLogFileUsed = true;
            return i;
        } catch (IOException ioe) {
            String msg = "Cannot write on the specified log file. "
                + "Make sure the path exists and you have write "
                + "permissions.";
            throw new BuildException(msg);
        } catch (ArrayIndexOutOfBoundsException aioobe) {
            String msg = "You must specify a log file when "
                + "using the -log argument";
            throw new BuildException(msg);
        }
    }

    private int processCustomArgument(String[] args, int i, String arg, ArgumentProcessorRegistry processorRegistry) {
        boolean processed = false;
        for (ArgumentProcessor processor : processorRegistry.getProcessors()) {
            int newI = processor.readArguments(args, i);
            if (newI != -1) {
                List<String> extraArgs = extraArguments.get(processor.getClass());
                if (extraArgs == null) {
                    extraArgs = new ArrayList<String>();
                    extraArguments.put(processor.getClass(), extraArgs);
                }
                for (; i < newI && i < args.length; i++) {
                    extraArgs.add(args[i]);
                }
                processed = true;
                break;
            }
        }
        if (!processed) {
            String msg = "Unknown argument: " + arg;
            System.err.println(msg);
            printUsage();
            throw new BuildException("");
        }
        return i;
    }

    private void processBuildFile(boolean searchForFile, String searchForThis) {
        if (buildFile == null) {
            if (searchForFile) {
                processSearchForFile(searchForThis);
            } else {
                processDefaultBuildFileSearch();
            }
        }

        validateBuildFile();
        normalizeBuildFile();
        loadPropertyFiles();
        if (msgOutputLevel >= Project.MSG_INFO) {
            System.out.println("Buildfile: " + buildFile);
        }
    }

    private void processSearchForFile(String searchForThis) {
        if (searchForThis != null) {
            buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
            if (buildFile == null) {
                throw new BuildException("Could not locate a build file!");
            }
        } else {
            processDefaultBuildFileSearch();
        }
    }

    private void processDefaultBuildFileSearch() {
        Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
        do {
            ProjectHelper helper = it.next();
            String searchForThis = helper.getDefaultBuildFile();
            if (msgOutputLevel >= Project.MSG_VERBOSE) {
                System.out.println("Searching the default build file: " + searchForThis);
            }
            buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
        } while (buildFile == null && it.hasNext());
        if (buildFile == null) {
            throw new BuildException("Could not locate a build file!");
        }
    }

    private void validateBuildFile() {
        if (!buildFile.exists()) {
            System.out.println("Buildfile: " + buildFile + " does not exist!");
            throw new BuildException("Build failed");
        }

        if (buildFile.isDirectory()) {
            File whatYouMeant = new File(buildFile, "build.xml");
            if (whatYouMeant.isFile()) {
                buildFile = whatYouMeant;
            } else {
                System.out.println("What? Buildfile: " + buildFile + " is a dir!");
                throw new BuildException("Build failed");
            }
        }
    }

    private void normalizeBuildFile() {
        buildFile = FileUtils.getFileUtils().normalize(buildFile.getAbsolutePath());
    }
