private void processArgs(String[] args) {
    ArgumentProcessorRegistry processorRegistry = ArgumentProcessorRegistry.getInstance();
    ArgProcessingState state = new ArgProcessingState();

    for (int i = 0; i < args.length; i++) {
        String arg = args[i];
        i = processSingleArg(args, i, processorRegistry, state);
    }

    finalizeProcessing(state);
}

/**
 * Processes a single command-line argument and returns the updated index.
 */
private int processSingleArg(String[] args, int i, ArgumentProcessorRegistry registry, ArgProcessingState state) {
    String arg = args[i];

    if (isHelpArg(arg)) {
        state.justPrintUsage = true;
    } else if (arg.equals("-version")) {
        state.justPrintVersion = true;
    } else if (arg.equals("-diagnostics")) {
        state.justPrintDiagnostics = true;
    } else if (isQuietArg(arg)) {
        state.msgOutputLevel = Project.MSG_WARN;
    } else if (isVerboseArg(arg)) {
        state.msgOutputLevel = Project.MSG_VERBOSE;
    } else if (isDebugArg(arg)) {
        state.msgOutputLevel = Project.MSG_DEBUG;
    } else if (isSilentArg(arg)) {
        state.silent = true;
    } else if (arg.equals("-noinput")) {
        state.allowInput = false;
    } else if (isLogfileArg(arg)) {
        i = handleLogfileArg(args, i, state);
    } else if (isBuildfileArg(arg)) {
        i = handleArgBuildFile(args, i);
    } else if (arg.equals("-listener")) {
        i = handleArgListener(args, i);
    } else if (arg.startsWith("-D")) {
        i = handleArgDefine(args, i);
    } else if (arg.equals("-logger")) {
        i = handleArgLogger(args, i);
    } else if (arg.equals("-inputhandler")) {
        i = handleArgInputHandler(args, i);
    } else if (isEmacsArg(arg)) {
        state.emacsMode = true;
    } else if (isProjectHelpArg(arg)) {
        state.projectHelp = true;
    } else if (isFindArg(arg)) {
        i = handleFindArg(args, i, state);
    } else if (arg.startsWith("-propertyfile")) {
        i = handleArgPropertyFile(args, i);
    } else if (isKeepGoingArg(arg)) {
        state.keepGoingMode = true;
    } else if (arg.equals("-nice")) {
        i = handleArgNice(args, i);
    } else if (LAUNCH_COMMANDS.contains(arg)) {
        throwInvalidLauncherArg(arg);
    } else if (arg.equals("-autoproxy")) {
        state.proxy = true;
    } else if (arg.startsWith("-")) {
        i = handleCustomArg(args, i, registry, state);
    } else {
        state.targets.addElement(arg);
    }

    return i;
}

/**
 * Handles -logfile/-l argument.
 */
private int handleLogfileArg(String[] args, int i, ArgProcessingState state) {
    try {
        File logFile = new File(args[i + 1]);
        i++;
        state.logTo = new PrintStream(new FileOutputStream(logFile));
        isLogFileUsed = true;
    } catch (IOException ioe) {
        throw new BuildException("Cannot write on the specified log file. "
            + "Make sure the path exists and you have write permissions.");
    } catch (ArrayIndexOutOfBoundsException aioobe) {
        throw new BuildException("You must specify a log file when using the -log argument");
    }
    return i;
}

/**
 * Handles -find/-s argument.
 */
private int handleFindArg(String[] args, int i, ArgProcessingState state) {
    state.searchForFile = true;
    if (i < args.length - 1) {
        state.searchForThis = args[++i];
    }
    return i;
}

/**
 * Handles custom arguments via registered ArgumentProcessors.
 */
private int handleCustomArg(String[] args, int i, ArgumentProcessorRegistry registry, ArgProcessingState state) {
    boolean processed = false;
    for (ArgumentProcessor processor : registry.getProcessors()) {
        int newI = processor.readArguments(args, i);
        if (newI != -1) {
            List<String> extraArgs = state.extraArguments.computeIfAbsent(processor.getClass(), k -> new ArrayList<>());
            for (int j = i; j <= newI && j < args.length; j++) {
                extraArgs.add(args[j]);
            }
            processed = true;
            i = newI;
            break;
        }
    }
    if (!processed) {
        throw new BuildException("Unknown argument: " + args[i] + "\n");
    }
    return i;
}

/**
 * Finalizes argument processing: version, diagnostics, help, build file search, etc.
 */
private void finalizeProcessing(ArgProcessingState state) {
    if (state.msgOutputLevel >= Project.MSG_VERBOSE || state.justPrintVersion) {
        printVersion(state.msgOutputLevel);
    }

    if (state.justPrintUsage || state.justPrintVersion || state.justPrintDiagnostics) {
        if (state.justPrintUsage) {
            printUsage();
        }
        if (state.justPrintDiagnostics) {
            Diagnostics.doReport(System.out, state.msgOutputLevel);
        }
        return;
    }

    if (buildFile == null) {
        if (state.searchForFile) {
            resolveBuildFileViaSearch(state.searchForThis);
        } else {
            resolveDefaultBuildFile();
        }
    }

    validateBuildFile();
    normalizeBuildFile();
    loadPropertyFiles();

    if (state.msgOutputLevel >= Project.MSG_INFO) {
        System.out.println("Buildfile: " + buildFile);
    }

    if (state.logTo != null) {
        out = state.logTo;
        err = state.logTo;
        System.setOut(out);
        System.setErr(err);
    }
    readyToRun = true;
}

/**
 * Resolves build file via -find search.
 */
private void resolveBuildFileViaSearch(String searchForThis) {
    if (searchForThis != null) {
        buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
        if (buildFile == null) {
            throw new BuildException("Could not locate a build file!");
        }
    } else {
        resolveDefaultBuildFileViaSearch();
    }
}

/**
 * Searches for default build file when -find is used without a suffix.
 */
private void resolveDefaultBuildFileViaSearch() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        String searchForThis = helper.getDefaultBuildFile();
        if (msgOutputLevel >= Project.MSG_VERBOSE) {
            System.out.println("Searching the default build file: " + searchForThis);
        }
        buildFile = findBuildFile(System.getProperty("user.dir"), searchForThis);
    } while (buildFile == null && it.hasNext());
    if (buildFile == null) {
        throw new BuildException("Could not locate a build file!");
    }
}

/**
 * Resolves default build file when no -find or -buildfile is specified.
 */
private void resolveDefaultBuildFile() {
    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
    do {
        ProjectHelper helper = it.next();
        buildFile = new File(helper.getDefaultBuildFile());
        if (msgOutputLevel >= Project.MSG_VERBOSE) {
            System.out.println("Trying the default build file: " + buildFile);
        }
    } while (!buildFile.exists() && it.hasNext());
}

/**
 * Validates that the build file exists and is not a directory.
 */
private void validateBuildFile() {
    if (!buildFile.exists()) {
        System.out.println("Buildfile: " + buildFile + " does not exist!");
        throw new BuildException("Build failed");
    }

    if (buildFile.isDirectory()) {
        File whatYouMeant = new File(buildFile, "build.xml");
        if (whatYouMeant.isFile()) {
            buildFile = whatYouMeant;
        } else {
            System.out.println("What? Buildfile: " + buildFile + " is a dir!");
            throw new BuildException("Build failed");
        }
    }
}

/**
 * Normalizes the build file path.
 */
private void normalizeBuildFile() {
    buildFile = FileUtils.getFileUtils().normalize(buildFile.getAbsolutePath());
}

/**
 * Throws an exception for invalid launcher arguments.
 */
private void throwInvalidLauncherArg(String arg) {
    String msg = "Ant's Main method is being handed "
            + "an option " + arg + " that is only for the launcher class."
            + "\nThis can be caused by a version mismatch between "
            + "the ant script/.bat file and Ant itself.";
