            }
        } else if (elementType == metaTypes.getAssociationClass()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCore().buildAssociationClass(fe, te);
        } else if (elementType == metaTypes.getAssociationRole()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCollaborations().buildAssociationRole(fe, fs, te, ts, u);
        } else if (elementType == metaTypes.getGeneralization()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCore().buildGeneralization(fe, te);
        } else if (elementType == metaTypes.getPackageImport()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCore().buildPackageImport(fe, te);
        } else if (elementType == metaTypes.getUsage()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCore().buildUsage(fe, te);
        } else if (elementType == metaTypes.getDependency()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCore().buildDependency(fe, te);
        } else if (elementType == metaTypes.getAbstraction()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCore().buildRealization(fe, te, ns);
        } else if (elementType == metaTypes.getLink()) {
            return (fe, fs, te, ts, u, ns, impl) -> getCommonBehavior().buildLink(fe, te);
        } else if (elementType == metaTypes.getExtend()) {
            return (fe, fs, te, ts, u, ns, impl) -> getUseCases().buildExtend(te, fe);
        } else if (elementType == metaTypes.getInclude()) {
            return (fe, fs, te, ts, u, ns, impl) -> getUseCases().buildInclude(fe, te);
        } else if (elementType == metaTypes.getTransition()) {
            return (fe, fs, te, ts, u, ns, impl) -> getStateMachines().buildTransition(fe, te);
        }
        return null;
    }

