        ? ((Boolean) unidirectional).booleanValue() : false;

    ConnectionBuilder builder = getBuilderForType(elementType);
    if (builder != null) {
        connection = builder.build(elementType, fromElement, fromStyle,
                toElement, toStyle, uni, namespace);
    }

    if (connection == null) {
        throw new IllegalModelElementConnectionException("Cannot make a "
