public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }

    try {
        Object stateMachine = getStateMachine(trans);
        Object context = Model.getFacade().getContext(stateMachine);

        Object found = findOperationInContext(context, opname);
        if (found != null) {
            return found;
        }

        Namespace pack = resolveNamespace(context, stateMachine);
        if (pack != null) {
            return findOperationInPackage(pack, opname);
        }

        return null;
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
}

private Object findOperationInContext(Object context, String opname) {
    if (!(context instanceof Classifier) && !(context instanceof BehavioralFeature)) {
        return null;
    }

    Classifier classifier = resolveClassifier(context);
    if (classifier == null) {
        return null;
    }

    return findOperationInClassifier(classifier, opname);
}

private Classifier resolveClassifier(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

private Object findOperationInClassifier(Classifier classifier, String opname) {
    List<Feature> features = classifier.getFeature();
    for (Feature f : features) {
        if (f instanceof Operation && opname.equals(f.getName())) {
            return f;
        }
    }
    return null;
}

private Namespace resolveNamespace(Object context, Object stateMachine) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }

    Classifier classifier = resolveClassifier(context);
    if (classifier == null) {
        return null;
    }

    Namespace namespace = classifier.getNamespace();
    while (namespace instanceof Classifier) {
        Namespace parent = namespace.getNamespace();
        if (parent == null) {
            break;
        }
        namespace = parent;
    }

    return namespace;
}

private Object findOperationInPackage(Namespace pack, String opname) {
    Collection<ModelElement> elements = pack.getOwnedElement();
    for (ModelElement me : elements) {
        if (me instanceof Classifier) {
            Object found = findOperationInClassifier((Classifier) me, opname);
            if (found != null) {
                return found;
            }
        }
    }
    return null;
}

