     * @since Ant 1.6
     */
    private void processArgs(String[] args) {
        ArgParsingContext context = new ArgParsingContext();
        ArgumentProcessorRegistry processorRegistry = ArgumentProcessorRegistry.getInstance();

        for (int i = 0; i < args.length; i++) {
            String arg = args[i];
            if (!handleArgument(arg, args, i, context, processorRegistry)) {
                // if it's no other arg, it may be the target
                targets.addElement(arg);
            }
        }

        finalizeArgs(context);
    }

    /**
     * Handles a single command-line argument. Returns true if the argument was handled.
     * Extracted to reduce cognitive complexity.
     */
    private boolean handleArgument(String arg, String[] args, int index,
                                   ArgParsingContext context, ArgumentProcessorRegistry registry) {
        if (arg.equals("-help") || arg.equals("-h")) {
            context.setPrintUsage(true);
            return true;
        } else if (arg.equals("-version")) {
            context.setPrintVersion(true);
            return true;
        } else if (arg.equals("-diagnostics")) {
            context.setPrintDiagnostics(true);
            return true;
        } else if (arg.equals("-quiet") || arg.equals("-q")) {
            msgOutputLevel = Project.MSG_WARN;
            return true;
        } else if (arg.equals("-verbose") || arg.equals("-v")) {
            msgOutputLevel = Project.MSG_VERBOSE;
            return true;
        } else if (arg.equals("-debug") || arg.equals("-d")) {
            msgOutputLevel = Project.MSG_DEBUG;
            return true;
        } else if (arg.equals("-silent") || arg.equals("-S")) {
            silent = true;
            return true;
        } else if (arg.equals("-noinput")) {
            allowInput = false;
            return true;
        } else if (arg.equals("-logfile") || arg.equals("-l")) {
            i = handleLogfileArg(args, i, context);
            return true;
        } else if (arg.equals("-buildfile") || arg.equals("-file")
                   || arg.equals("-f")) {
            i = handleArgBuildFile(args, i);
            return true;
        } else if (arg.equals("-listener")) {
            i = handleArgListener(args, i);
            return true;
        } else if (arg.startsWith("-D")) {
            i = handleArgDefine(args, i);
            return true;
        } else if (arg.equals("-logger")) {
            i = handleArgLogger(args, i);
            return true;
        } else if (arg.equals("-inputhandler")) {
            i = handleArgInputHandler(args, i);
            return true;
        } else if (arg.equals("-emacs") || arg.equals("-e")) {
            emacsMode = true;
            return true;
        } else if (arg.equals("-projecthelp") || arg.equals("-p")) {
            projectHelp = true;
            return true;
        } else if (arg.equals("-find") || arg.equals("-s")) {
            i = handleFindArg(args, i, context);
            return true;
        } else if (arg.startsWith("-propertyfile")) {
            i = handleArgPropertyFile(args, i);
            return true;
        } else if (arg.equals("-k") || arg.equals("-keep-going")) {
            keepGoingMode = true;
            return true;
        } else if (arg.equals("-nice")) {
            i = handleArgNice(args, i);
            return true;
        } else if (LAUNCH_COMMANDS.contains(arg)) {
            String msg = "Ant's Main method is being handed "
                    + "an option " + arg + " that is only for the launcher class."
                    + "\nThis can be caused by a version mismatch between "
                    + "the ant script/.bat file and Ant itself.";
            throw new BuildException(msg);
        } else if (arg.equals("-autoproxy")) {
            proxy = true;
            return true;
        } else if (arg.startsWith("-")) {
            return tryProcessCustomArgument(arg, args, i, context, registry);
        }
        return false;
    }

    /**
     * Attempts to process a custom argument with registered processors.
     * Returns true if processed.
     */
    private boolean tryProcessCustomArgument(String arg, String[] args, int index,
                                             ArgParsingContext context, ArgumentProcessorRegistry registry) {
        for (ArgumentProcessor processor : registry.getProcessors()) {
            int newI = processor.readArguments(args, index);
            if (newI != -1) {
                List<String> extraArgs = extraArguments.computeIfAbsent(processor.getClass(),
                        k -> new ArrayList<>());
                for (int j = index; j <= newI && j < args.length; j++) {
                    extraArgs.add(args[j]);
                }
                return true;
            }
        }
        // we don't have any more args to recognize!
        String msg = "Unknown argument: " + arg;
        System.err.println(msg);
        printUsage();
        throw new BuildException("");
    }

    /**
     * Handles the -logfile argument.
     */
    private void handleLogfileArg(String[] args, int index, ArgParsingContext context) {
        try {
            File logFile = new File(args[index + 1]);
            index++;
            PrintStream logTo = new PrintStream(new FileOutputStream(logFile));
            context.setLogStream(logTo);
            isLogFileUsed = true;
        } catch (IOException ioe) {
            String msg = "Cannot write on the specified log file. "
                + "Make sure the path exists and you have write "
                + "permissions.";
            throw new BuildException(msg);
        } catch (ArrayIndexOutOfBoundsException aioobe) {
            String msg = "You must specify a log file when "
                + "using the -log argument";
            throw new BuildException(msg);
        }
    }

