     * Handles the -find argument.
     */
    private int handleFindArg(String[] args, int index, ArgParsingContext context) {
        context.setSearchForFile(true);
        // eat up next arg if present, default to build.xml
        if (index < args.length - 1) {
            context.setSearchFile(args[++index]);
        }
        return index;
    }

    /**
     * Finalizes command-line argument processing.
     */
    private void finalizeArgs(ArgParsingContext context) {
        if (msgOutputLevel >= Project.MSG_VERBOSE || context.isPrintVersion()) {
            printVersion(msgOutputLevel);
        }

        if (context.isPrintUsage() || context.isPrintVersion() || context.isPrintDiagnostics()) {
            if (context.isPrintUsage()) {
                printUsage();
            }
            if (context.isPrintDiagnostics()) {
                Diagnostics.doReport(System.out, msgOutputLevel);
            }
            return;
        }

        // if buildFile was not specified on the command line,
        if (buildFile == null) {
            // but -find then search for it
            if (context.isSearchForFile()) {
                if (context.getSearchFile() != null) {
                    buildFile = findBuildFile(System.getProperty("user.dir"), context.getSearchFile());
                    if (buildFile == null) {
                        throw new BuildException("Could not locate a build file!");
                    }
                } else {
                    // no search file specified: so search an existing default file
                    Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
                    do {
                        ProjectHelper helper = it.next();
                        String defaultBuildFile = helper.getDefaultBuildFile();
                        if (msgOutputLevel >= Project.MSG_VERBOSE) {
                            System.out.println("Searching the default build file: " + defaultBuildFile);
                        }
                        buildFile = findBuildFile(System.getProperty("user.dir"), defaultBuildFile);
                    } while (buildFile == null && it.hasNext());
                    if (buildFile == null) {
                        throw new BuildException("Could not locate a build file!");
                    }
                }
            } else {
                // no build file specified: so search an existing default file
                Iterator<ProjectHelper> it = ProjectHelperRepository.getInstance().getHelpers();
                do {
                    ProjectHelper helper = it.next();
                    buildFile = new File(helper.getDefaultBuildFile());
                    if (msgOutputLevel >= Project.MSG_VERBOSE) {
                        System.out.println("Trying the default build file: " + buildFile);
                    }
                } while (!buildFile.exists() && it.hasNext());
            }
        }

        // make sure buildfile exists
        if (!buildFile.exists()) {
            System.out.println("Buildfile: " + buildFile + " does not exist!");
            throw new BuildException("Build failed");
        }

        if (buildFile.isDirectory()) {
            File whatYouMeant = new File(buildFile, "build.xml");
            if (whatYouMeant.isFile()) {
                buildFile = whatYouMeant;
            } else {
                System.out.println("What? Buildfile: " + buildFile + " is a dir!");
                throw new BuildException("Build failed");
            }
        }

        // Normalize buildFile for re-import detection
        buildFile = FileUtils.getFileUtils().normalize(buildFile.getAbsolutePath());

        // Load the property files specified by -propertyfile
        loadPropertyFiles();

        if (msgOutputLevel >= Project.MSG_INFO) {
            System.out.println("Buildfile: " + buildFile);
        }

        if (context.getLogStream() != null) {
            out = context.getLogStream();
            err = context.getLogStream();
            System.setOut(out);
            System.setErr(err);
        }
        readyToRun = true;
    }

    /**
     * Nested class to encapsulate argument parsing context.
     * Used to reduce cognitive complexity in processArgs.
     */
    private static class ArgParsingContext {
        private boolean printUsage;
        private boolean printVersion;
        private boolean printDiagnostics;
        private boolean searchForFile;
        private String searchFile;
        private PrintStream logStream;

        public void setPrintUsage(boolean printUsage) { this.printUsage = printUsage; }
        public void setPrintVersion(boolean printVersion) { this.printVersion = printVersion; }
        public void setPrintDiagnostics(boolean printDiagnostics) { this.printDiagnostics = printDiagnostics; }
        public void setSearchForFile(boolean searchForFile) { this.searchForFile = searchForFile; }
        public void setSearchFile(String searchFile) { this.searchFile = searchFile; }
        public void setLogStream(PrintStream logStream) { this.logStream = logStream; }

        public boolean isPrintUsage() { return printUsage; }
        public boolean isPrintVersion() { return printVersion; }
        public boolean isPrintDiagnostics() { return printDiagnostics; }
        public boolean isSearchForFile() { return searchForFile; }
        public String getSearchFile() { return searchFile; }
        public PrintStream getLogStream() { return logStream; }
    }

