        Classifier classifier = getClassifier(context);

        if (classifier != null) {
            Object found = findInClassifier(classifier, opname);
            if (found != null) {
                return found;
            }
        }

        Namespace pack = getPackage(context, classifier);
        if (pack != null) {
            Object found = findInPackage(pack, opname);
            if (found != null) {
                return found;
            }
        }

        return null;
    } catch (InvalidObjectException e) {
