private Classifier getClassifier(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

private Object findInClassifier(Classifier classifier, String opname) {
    for (Feature f : classifier.getFeature()) {
        if (isOperationNamed(f, opname)) {
            return f;
        }
    }
    return null;
}

private boolean isOperationNamed(Feature f, String opname) {
    return f instanceof Operation && opname.equals(f.getName());
}

private Namespace getPackage(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier == null) {
        return null;
    }

    Namespace parent = classifier.getNamespace();
    while (parent instanceof Classifier) {
        if (parent.getNamespace() == null) {
            break;
        }
        parent = parent.getNamespace();
    }
    return parent != null ? parent : null;
}

private Object findInPackage(Namespace pack, String opname) {
    for (ModelElement me : pack.getOwnedElement()) {
        if (me instanceof Classifier) {
            Object found = findInClassifier((Classifier) me, opname);
            if (found != null) {
                return found;
            }
        }
    }
    return null;
}

public Object findOperationByName(Object trans, String opname) {
    if (!(trans instanceof Transition)) {
        throw new IllegalArgumentException();
    }

    try {
        Object sm = getStateMachine(trans);
        Object context = Model.getFacade().getContext(sm);
        Classifier classifier = extractClassifier(context);

        Object result = findOperationInClassifier(classifier, opname);
        if (result != null) {
            return result;
        }

        Namespace pack = extractNamespace(context, classifier);
        result = findOperationInNamespace(pack, opname);
        if (result != null) {
            return result;
        }

        return null;
    } catch (InvalidObjectException e) {
        throw new InvalidElementException(e);
    }
}

private Classifier extractClassifier(Object context) {
    if (context instanceof Classifier) {
        return (Classifier) context;
    }
    if (context instanceof BehavioralFeature) {
        return ((BehavioralFeature) context).getOwner();
    }
    return null;
}

private Object findOperationInClassifier(Classifier classifier, String opname) {
    if (classifier == null) {
        return null;
    }
    List<Feature> features = classifier.getFeature();
    for (Feature f : features) {
        if (isOperationNamed(f, opname)) {
            return f;
        }
    }
    return null;
}

private boolean isOperationNamed(Feature f, String opname) {
    return f instanceof Operation && opname.equals(f.getName());
}

private Namespace extractNamespace(Object context, Classifier classifier) {
    if (context instanceof UmlPackage) {
        return (Namespace) context;
    }
    if (classifier == null) {
        return null;
    }
    return findTopLevelNamespace(classifier.getNamespace());
}

private Namespace findTopLevelNamespace(Namespace ns) {
    Namespace parent = ns;
    while (parent instanceof Classifier && parent.getNamespace() != null) {
        parent = parent.getNamespace();
    }
    return parent instanceof Namespace ? (Namespace) parent : null;
}

private Object findOperationInNamespace(Namespace pack, String opname) {
    if (pack == null) {
        return null;
    }
    Collection<ModelElement> mes = pack.getOwnedElement();
    for (ModelElement me : mes) {
        if (me instanceof Classifier) {
            Classifier classifier2 = (Classifier) me;
            Object result = findOperationInClassifier(classifier2, opname);
            if (result != null) {
                return result;
            }
        }
    }
    return null;
}

def formatETA(self, prefix, eta):
    if eta is None:
        return []
    if eta < 60:
        return ["< 1 min"]
    eta_parts = ["~"]
    eta_secs = eta
    if eta_secs > 3600:
        eta_parts.append("%d hrs" % (eta_secs / 3600))
        eta_secs %= 3600
    if eta_secs > 60:
        eta_parts.append("%d mins" % (eta_secs / 60))
        eta_secs %= 60
    abstime = time.strftime("%H:%M", time.localtime(util.now() + eta))
    return [prefix, " ".join(eta_parts), "at %s" % abstime]

def getBox(self, status, brcounts):
    # getState() returns offline, idle, or building
    state, builds = self.original.getState()

    # look for upcoming builds. We say the state is "waiting" if the
    # builder is otherwise idle and there is a scheduler which tells us a
    # build will be performed some time in the near future. TODO: this
    # functionality used to be in BuilderStatus.. maybe this code should
    # be merged back into it.
    upcoming = []
    builderName = self.original.getName()
    for s in status.getSchedulers():
        if builderName in s.listBuilderNames():
            upcoming.extend(s.getPendingBuildTimes())
    if state == "idle" and upcoming:
        state = "waiting"

    if state == "building":
        text = ["building"]
        if builds:
            for b in builds:
                eta = b.getETA()
                text.extend(self.formatETA("ETA in", eta))
    elif state == "offline":
        text = ["offline"]
    elif state == "idle":
        text = ["idle"]
    elif state == "waiting":
        text = ["waiting"]
    else:
        # just in case I add a state and forget to update this
        text = [state]

    # TODO: for now, this pending/upcoming stuff is in the "current
    # activity" box, but really it should go into a "next activity" row
    # instead. The only times it should show up in "current activity" is
    # when the builder is otherwise idle.

    # are any builds pending? (waiting for a slave to be free)
    brcount = brcounts[builderName]
    if brcount:
        text.append("%d pending" % brcount)
    for t in sorted(upcoming):
        if t is not None:
            eta = t - util.now()
            text.extend(self.formatETA("next in", eta))
    return Box(text, class_="Activity " + state)

