        self._connect_last_element_to_next_sibling(newChildsLastElement)
    else:
        self._connect_to_next_child(newChild, newChildsLastElement, position)

    self._update_previous_and_next_links(newChildsLastElement, newChild)
    self.contents.insert(position, newChild)

def _is_string_like_and_not_navigable(self, newChild):
    return (isinstance(newChild, basestring)
            or isinstance(newChild, unicode)) \
        and not isinstance(newChild, NavigableString)

def _has_parent_and_is_not_orphan(self, newChild):
    return hasattr(newChild, 'parent') and newChild.parent is not None

def _handle_inserting_existing_child(self, newChild, position):
    if newChild.parent == self:
        index = self.find(newChild)
        if index is not None and index < position:
            position -= 1
    newChild.extract()

def _setup_new_child_relations(self, newChild, position):
    previousChild = None
    if position == 0:
        newChild.previousSibling = None
        newChild.previous = self
    else:
        previousChild = self.contents[position - 1]
        newChild.previousSibling = previousChild
        newChild.previousSibling.nextSibling = newChild
        newChild.previous = previousChild._lastRecursiveChild()
    if newChild.previous:
        newChild.previous.next = newChild

def _connect_last_element_to_next_sibling(self, lastElement):
    parent = self
    parentsNextSibling = None
    while not parentsNextSibling:
        parentsNextSibling = parent.nextSibling
        parent = parent.parent
        if not parent:
            break
    if parentsNextSibling:
        lastElement.next = parentsNextSibling
    else:
        lastElement.next = None

def _connect_to_next_child(self, newChild, lastElement, position):
    nextChild = self.contents[position]
    newChild.nextSibling = nextChild
    if newChild.nextSibling:
        newChild.nextSibling.previousSibling = newChild
    lastElement.next = nextChild

def _update_previous_and_next_links(self, lastElement, newChild):
    if lastElement.next:
        lastElement.next.previous = lastElement

def insert(self, position, newChild):
    if self._is_string_like_but_not_navigable(newChild):
        newChild = NavigableString(newChild)

    position = min(position, len(self.contents))

    if hasattr(newChild, 'parent') and newChild.parent is not None:
        if self._extract_and_position_adjustment_needed(newChild, position):
            position -= 1
        newChild.extract()

    newChild.parent = self

    if position == 0:
        self._setup_first_position(newChild)
    else:
        self._setup_middle_or_last_position(newChild, position)

    if position >= len(self.contents):
        self._setup_tail_linkage(newChild)
    else:
        self._setup_linkage_with_next_child(newChild, position)

def _is_string_like_but_not_navigable(self, newChild):
    return (isinstance(newChild, basestring) or isinstance(newChild, unicode)) and not isinstance(newChild, NavigableString)

def _extract_and_position_adjustment_needed(self, newChild, position):
    if newChild.parent != self:
        return False
    index = self.find(newChild)
    return index is not None and index < position

def _setup_first_position(self, newChild):
    newChild.previousSibling = None
    newChild.previous = self

def _setup_middle_or_last_position(self, newChild, position):
    previousChild = self.contents[position - 1]
    newChild.previousSibling = previousChild
    previousChild.nextSibling = newChild
    newChild.previous = previousChild._lastRecursiveChild()

def _setup_linkage_with_next_child(self, newChild, position):
    nextChild = self.contents[position]
    newChild.nextSibling = nextChild
    if nextChild:
        nextChild.previousSibling = newChild
    newChild._lastRecursiveChild().next = nextChild

def _setup_tail_linkage(self, newChild):
    newChild.nextSibling = None
    last = newChild._lastRecursiveChild()
    parent = self
    while parent:
        next_sibling = parent.nextSibling
        if next_sibling:
            last.next = next_sibling
            return
        parent = parent.parent

    if (isinstance(newChild, basestring)
        or isinstance(newChild, unicode)) \
        and not isinstance(newChild, NavigableString):
        newChild = NavigableString(newChild)

    position = min(position, len(self.contents))

    if hasattr(newChild, 'parent') and newChild.parent is not None:
        self._handleReinsertedChild(newChild, position)

    newChild.parent = self

    idxForInsertion = self._calculateInsertionIndex(newChild, position)
    self.contents.insert(idxForInsertion, newChild)

    self._setupChildLinks(newChild, position)

    lastElement = newChild._lastRecursiveChild()

    if position >= len(self.contents):
        self._setupTailForLastChild(lastElement)
    else:
        nextChild = self.contents[position]
        newChild.nextSibling = nextChild
        if newChild.nextSibling:
            newChild.nextSibling.previousSibling = newChild
        lastElement.next = nextChild

    if lastElement.next:
        lastElement.next.previous = lastElement

def _handleReinsertedChild(self, newChild, position):
    """Handle extraction and index adjustment when reinserting an existing child."""
    if newChild.parent == self:
       =index = self.find(newChild)
        if index is not None and index < position:
            position -= 1
    newChild.extract()

def _calculateInsertionIndex(self, newChild, position):
    """Calculate the index at which to insert the new child."""
    return 0 if position == 0 else position

def _setupChildLinks(self, newChild, position):
    """Set up prev/next and sibling links for the inserted child."""
    previousChild = None
    if position != 0:
        previousChild = self.contents[position - 1]
        newChild.previousSibling = previousChild
        if previousChild:
            previousChild.nextSibling = newChild
        if previousChild:
            newChild.previous = previousChild._lastRecursiveChild()
    else:
        newChild.previousSibling = None
        newChild.previous = self

    if newChild.previous:
        newChild.previous.next = newChild

def _setupTailForLastChild(self, lastElement):
    """Set up the 'next' link for the last element when inserting at end."""
    parent = self
    parentsNextSibling = None
    while not parentsNextSibling and parent:
        parentsNextSibling = parent.nextSibling
        parent = parent.parent
    if parentsNextSibling:
        lastElement.next = parentsNextSibling
    else:
        lastElement.next = None

