def insert(self, position, newChild):
    if self._isStringButNotNavigable(newChild):
        newChild = NavigableString(newChild)

    position = min(position, len(self.contents))
    if self._hasParentAndIsNotSelf(newChild):
        self._handleInsertingExistingChild(newChild, position)

    newChild.parent = self
    previousChild = None
    if position == 0:
        newChild.previousSibling = None
        newChild.previous = self
    else:
        previousChild = self.contents[position-1]
        newChild.previousSibling = previousChild
        newChild.previousSibling.nextSibling = newChild
        newChild.previous = previousChild._lastRecursiveChild()
    if newChild.previous:
        newChild.previous.next = newChild

    newChildsLastElement = newChild._lastRecursiveChild()

    if position >= len(self.contents):
        newChild.nextSibling = None

        parent = self
        parentsNextSibling = None
        while not parentsNextSibling:
            parentsNextSibling = parent.nextSibling
            parent = parent.parent
            if not parent:
                break
        if parentsNextSibling:
            newChildsLastElement.next = parentsNextSibling
        else:
            newChildsLastElement.next = None
    else:
        nextChild = self.contents[position]
        newChild.nextSibling = nextChild
        if newChild.nextSibling:
            newChild.nextSibling.previousSibling = newChild
        newChildsLastElement.next = nextChild

    if newChildsLastElement.next:
        newChildsLastElement.next.previous = newChildsLastElement
    self.contents.insert(position, newChild)

def _isStringButNotNavigable(self, newChild):
    return (isinstance(newChild, basestring)
            or isinstance(newChild, unicode)) \
           and not isinstance(newChild, NavigableString)

def _hasParentAndIsNotSelf(self, newChild):
    return hasattr(newChild, 'parent') and newChild.parent is not None

def _handleInsertingExistingChild(self, newChild, position):
    if newChild.parent == self:
        index = self.find(newChild)
        if index is not None and index < position:
            position -= 1
    newChild.extract()

def properties_for_id_with_scheme(item_id, prefixes, refines):
    ans = {}
    if item_id:
        for elem in refines[item_id]:
            key = elem.get('property')
            if key:
                val = (elem.text or '').strip()
                if val:
                    scheme_ns, scheme = _extract_scheme(elem, prefixes)
                    ans[key] = (scheme_ns, scheme, val)
    return ans


def _extract_scheme(elem, prefixes):
    scheme = elem.get('scheme') or None
    if scheme is None:
        return None, None
    p, sep, r = scheme.partition(':')
    if not sep or not p or not r:
        return None, None
    ns = prefixes.get(p)
    if ns:
        return ns, r
    return None, scheme

def properties_for_id_with_scheme(item_id, prefixes, refines):
    ans = {}
    if item_id:
        for elem in refines[item_id]:
            key = elem.get('property')
            if key:
                val = (elem.text or '').strip()
                if val:
                    scheme_ns, scheme = _parse_scheme(elem, prefixes)
                    ans[key] = (scheme_ns, scheme, val)
    return ans


def _parse_scheme(elem, prefixes):
    scheme = elem.get('scheme') or None
    if scheme is None:
        return None, None

    p, _, r = scheme.partition(':')
    if not p or not r:
        return None, scheme

    ns = prefixes.get(p)
    if ns:
        return ns, r

    return None, scheme

