def properties_for_id_with_scheme(item_id, prefixes, refines):
    ans = {}
    if not item_id:
        return ans

    for elem in refines[item_id]:
        key = elem.get('property')
        if not key:
            continue

        val = (elem.text or '').strip()
        if not val:
            continue

        scheme = elem.get('scheme')
        scheme_ns = None
        if scheme is not None:
            p, sep, r = scheme.partition(':')
            if p and sep and r:
                ns = prefixes.get(p)
                if ns:
                    scheme_ns = ns
                    scheme = r

        ans[key] = (scheme_ns, scheme, val)

    return ans

def properties_for_id_with_scheme(item_id, prefixes, refines):
    ans = {}
    if not item_id:
        return ans

    for elem in refines[item_id]:
        key = elem.get('property')
        if not key:
            continue

        val = (elem.text or '').strip()
        if not val:
            continue

        scheme = elem.get('scheme') or None
        scheme_ns = None

        if scheme is not None:
            parts = scheme.partition(':')
            if len(parts) == 3 and parts[0] and parts[2]:
                ns = prefixes.get(parts[0])
                if ns:
                    scheme_ns = ns
                    scheme = parts[2]

        ans[key] = (scheme_ns, scheme, val)

    return ans

