        '''
        self.listeners.add(listener)

    def _notify_single_listener(self, listener, event, ids):
        '''
        Notify a single listener and handle exceptions gracefully.
        '''
        try:
            listener(event, ids)
        except Exception:
            traceback.print_exc()

    def notify(self, event, ids=[]):
        'Notify all listeners'
        for listener in self.listeners:
            self._notify_single_listener(listener, event, ids)

