    private synchronized void setupConnection() throws IOException {
      short ioFailures = 0;
      short timeoutFailures = 0;
      while (true) {
        try {
          setupSocketAndConnect();
          return;
        } catch (ConnectTimeoutException toe) {
          handleTimeoutException(toe, timeoutFailures++, maxRetriesOnSocketTimeouts);
          timeoutFailures = updateFailureCount(timeoutFailures, ioFailures);
