      node = findMatchingNodeByIP(rackNodes, host);
    }

    // If we can't even choose rack local, just choose any node in the
    // cluster.
    if (node == null) {
      node = (DatanodeDescriptor)getNetworkTopology()
                                 .chooseRandom(NodeBase.ROOT);
    }
  }
  return node;
}

/**
 * Find a datanode in the list whose IP address matches the given address
 */
private DatanodeDescriptor findMatchingNodeByIP(List<Node> nodes, String ipAddr) {
  // Try something machine local.
  for (Node rackNode : nodes) {
    if (((DatanodeDescriptor) rackNode).getIpAddr().equals(ipAddr)) {
      return (DatanodeDescriptor) rackNode;
    }
  }

  // Try something rack local.
  if (!nodes.isEmpty()) {
    return (DatanodeDescriptor) (nodes
        .get(DFSUtil.getRandom().nextInt(nodes.size())));
  }
  return null;
}

