  }
  if (node == null) {
    node = findBestDatanodeDescriptorFallback(dnId);
  }
  return node;
}

/**
 * Attempts to find a suitable datanode descriptor using fallback logic:
 * first tries machine-local, then rack-local, and finally any node in the cluster.
 *
 * @param dnId the parsed DatanodeID from the input address
 * @return a DatanodeDescriptor matching the fallback criteria, or null if none found
 */
private DatanodeDescriptor findBestDatanodeDescriptorFallback(DatanodeID dnId) {
  String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
  List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);

  if (rackNodes != null) {
    DatanodeDescriptor node = findMachineLocalNode(rackNodes, dnId.getIpAddr());
    if (node == null && !rackNodes.isEmpty()) {
      node = findRandomRackLocalNode(rackNodes);
    }
    return node;
  }

  // Fallback to any node in the cluster
  return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
}

/**
 * Searches for a machine-local node (matching IP address) in the given rack nodes list.
 *
 * @param rackNodes list of nodes in the resolved rack
 * @param targetIp the target IP address to match
 * @return the first matching DatanodeDescriptor, or null if none found
 */
private DatanodeDescriptor findMachineLocalNode(List<Node> rackNodes, String targetIp) {
  for (Node rackNode : rackNodes) {
    DatanodeDescriptor dd = (DatanodeDescriptor) rackNode;
    if (dd.getIpAddr().equals(targetIp)) {
      return dd;
    }
  }
  return null;
}

/**
 * Selects a random node from the given rack nodes list.
 *
 * @param rackNodes list of nodes in the rack
 * @return a randomly selected DatanodeDescriptor from the list
 */
private DatanodeDescriptor findRandomRackLocalNode(List<Node> rackNodes) {
  return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
}

