    if (node == null) {
      // Extracted helper to reduce complexity
      node = findBestDatanodeDescriptor(dnId);
    }
    return node;
  }

  /**
   * Find best DatanodeDescriptor when no direct hit is found.
   * Tries machine-local, rack-local, then random.
   *
   * @param dnId DatanodeID with parsed host/port info
   * @return best matching DatanodeDescriptor
   */
  private DatanodeDescriptor findBestDatanodeDescriptor(DatanodeID dnId) {
    String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
    List<Node> rackNodes = getNetworkTopology().getDatanodesInRack(networkLocation);

    if (rackNodes != null && !rackNodes.isEmpty()) {
      // Try machine local
      for (Node rackNode : rackNodes) {
        DatanodeDescriptor dd = (DatanodeDescriptor) rackNode;
        if (dd.getIpAddr().equals(dnId.getIpAddr())) {
          return dd;
        }
      }

      // Try rack local (random)
      return (DatanodeDescriptor) rackNodes.get(DFSUtil.getRandom().nextInt(rackNodes.size()));
    }

    // Fall back to any node in cluster
    return (DatanodeDescriptor) getNetworkTopology().chooseRandom(NodeBase.ROOT);
  }

