private static void handleOption(String arg, String[] args, int i, int level, String portFile, boolean restore, boolean gui, boolean noPlugins, boolean noStartupScripts, String scriptFile, String userDir)
{
	if(arg.equals("-usage"))
	{
		version();
		System.err.println();
		usage();
		System.exit(1);
	}
	else if(arg.equals("-version"))
	{
		version();
		System.exit(1);
	}
	else if(arg.equals("-nosettings"))
		settingsDirectory = null;
	else if(arg.startsWith("-settings="))
		settingsDirectory = arg.substring(10);
	else if(arg.startsWith("-noserver"))
		portFile = null;
	else if(arg.equals("-server"))
		portFile = "server";
	else if(arg.startsWith("-server="))
		portFile = arg.substring(8);
	else if(arg.startsWith("-background"))
		background = true;
	else if(arg.equals("-nogui"))
		gui = false;
	else if(arg.equals("-norestore"))
		restore = false;
	else if(arg.equals("-noplugins"))
		noPlugins = true;
	else if(arg.equals("-nostartupscripts"))
		noStartupScripts = true;
	else if(arg.startsWith("-run="))
		scriptFile = arg.substring(5);
	else
	{
		System.err.println("Unknown option: "
			+ arg);
		usage();
		System.exit(1);
	}
	args[i] = null;
}

