public void processKeyEvent(KeyEvent evt)
	{
		if(isClosed())
			return;

		if(shouldSkipKeyEventProcessing(evt))
			return;

		evt = KeyEventWorkaround.processKeyEvent(evt);
		if(evt == null)
			return;

		switch(evt.getID())
		{
		case KeyEvent.KEY_TYPED:
			handleKeyTyped(evt);
			break;
		case KeyEvent.KEY_PRESSED:
			handleKeyPressed(evt);
			break;
		case KeyEvent.KEY_RELEASED:
			handleKeyReleased(evt);
			break;
		}

		if(!evt.isConsumed())
			super.processKeyEvent(evt);
	}

	private boolean shouldSkipKeyEventProcessing(KeyEvent evt)
	{
		if(isFocusOwnerWithComponentInputHandler(evt))
			return true;

		if(isFocusOwnerWithTextComponentKeymap(evt))
			return true;

		return evt.isConsumed();
	}

	private boolean isFocusOwnerWithComponentInputHandler(KeyEvent evt)
	{
		if(!(getFocusOwner() instanceof JComponent))
			return false;

		JComponent comp = (JComponent)getFocusOwner();
		InputMap map = comp.getInputMap();
		ActionMap am = comp.getActionMap();

		if(map == null || am == null || !comp.isEnabled())
			return false;

		Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
		return binding != null && am.get(binding) != null;
	}

	private boolean isFocusOwnerWithTextComponentKeymap(KeyEvent evt)
	{
		if(!(getFocusOwner() instanceof JTextComponent))
			return false;

		JTextComponent textComponent = (JTextComponent)getFocusOwner();

		if(evt.getID() == KeyEvent.KEY_PRESSED)
		{
			switch(evt.getKeyCode())
			{
			case KeyEvent.VK_BACK_SPACE:
			case KeyEvent.VK_TAB:
			case KeyEvent.VK_ENTER:
				return true;
			}
		}

		Keymap keymap = textComponent.getKeymap();
		return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
	}

	private void handleKeyTyped(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			/* keyEventInterceptor.keyTyped(evt) */;
		else if(inputHandler.isPrefixActive()
			&& !getTextArea().hasFocus())
			inputHandler.keyTyped(evt);
	}

	private void handleKeyPressed(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			keyEventInterceptor.keyPressed(evt);
		else
			inputHandler.keyPressed(evt);
	}

	private void handleKeyReleased(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			keyEventInterceptor.keyReleased(evt);
		else
			inputHandler.keyReleased(evt);
	}

