	private static CommandLineArgs parseCommandLine(String[] args)
	{
		CommandLineArgs params = new CommandLineArgs();
		int level = Log.WARNING;
		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		params.logLevel = level;

		boolean endOpts = false;
		params.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		params.portFile = "server";
		params.restore = true;
		params.gui = true;
		params.noPlugins = false;
		params.noStartupScripts = false;
		params.userDir = System.getProperty("user.dir");
		params.scriptFile = null;

		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			else if(arg.length() == 0)
				args[i] = null;
			else if(arg.startsWith("-") && !endOpts)
			{
				if(arg.equals("--"))
					endOpts = true;
				else if(arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if(arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if(arg.equals("-nosettings"))
					params.settingsDirectory = null;
				else if(arg.startsWith("-settings="))
					params.settingsDirectory = arg.substring(10);
				else if(arg.startsWith("-noserver"))
					params.portFile = null;
				else if(arg.equals("-server"))
					params.portFile = "server";
				else if(arg.startsWith("-server="))
					params.portFile = arg.substring(8);
				else if(arg.startsWith("-background"))
					params.background = true;
				else if(arg.equals("-nogui"))
					params.gui = false;
				else if(arg.equals("-norestore"))
					params.restore = false;
				else if(arg.equals("-noplugins"))
					params.noPlugins = true;
				else if(arg.equals("-nostartupscripts"))
					params.noStartupScripts = true;
				else if(arg.startsWith("-run="))
					params.scriptFile = arg.substring(5);
				else
				{
					System.err.println("Unknown option: "
						+ arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}

		if(params.settingsDirectory != null && params.portFile != null)
			params.portFile = MiscUtilities.constructPath(params.settingsDirectory,params.portFile);
		else
			params.portFile = null;

		return params;
	}

	private static void handleRemoteInstance(String portFile, boolean restore, String[] args, String scriptFile)
	{
		if(portFile == null || !new File(portFile).exists())
			return;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(restore,args,scriptFile);
			out.writeUTF(script);
			out.close();
			System.exit(0);
		}
		catch(Exception e)
		{
			Log.log(Log.NOTICE,jEdit.class,"An error occurred while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that jEdit crashed and/or exited abnormally the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
		}
	}

	private static void showSplash(String settingsDirectory)
	{
		if(settingsDirectory == null || !new File(settingsDirectory,"nosplash").exists())
			GUIUtilities.showSplashScreen();
	}

	private static void prepareSettingsDirectory(String settingsDirectory)
	{
		if(settingsDirectory == null)
		{
			logWriter = null;
			return;
		}
		File dir = new File(settingsDirectory);
		if(!dir.exists())
			dir.mkdirs();
		File macrosDir = new File(settingsDirectory,"macros");
		if(!macrosDir.exists())
			macrosDir.mkdir();

		String logPath = MiscUtilities.constructPath(settingsDirectory,"activity.log");
		backupSettingsFile(new File(logPath));

		try
		{
			logWriter = new BufferedWriter(new FileWriter(logPath));
		}
		catch(Exception e)
		{
			e.printStackTrace();
			logWriter = null;
		}
