		}
		Log.log(Log.MESSAGE,jEdit.class,"jEdit home directory is " + jEditHome);
		jars = new Vector();
		EditBus.addToBus(new SettingsReloader());
		SwingUtilities.invokeLater(new Runnable()
		{
