				UIManager.setLookAndFeel(lf);
		}
		catch(Exception e)
		{
			Log.log(Log.ERROR,jEdit.class,e);
		}
		UIDefaults defaults = UIManager.getDefaults();
		if(jEdit.getBooleanProperty("textColors"))
		{
