    /**
     * Creates the chart area rectangle based on the available space and scaling.
     * 
     * @param available  the available drawing area.
     * @return the chart area rectangle.
     */
    private Rectangle2D createChartArea(Rectangle2D available) {
        double drawWidth = available.getWidth();
        double drawHeight = available.getHeight();

        // Apply scaling adjustments
        if (drawWidth < this.minimumDrawWidth || drawWidth > this.maximumDrawWidth) {
            drawWidth = this.scaleX == 1.0 ? available.getWidth() / this.scaleX : this.minimumDrawWidth;
        } else if (drawWidth > this.maximumDrawWidth) {
            drawWidth = this.maximumDrawWidth;
        }

        if (drawHeight < this.minimumDrawHeight || drawHeight > this.maximumDrawHeight) {
            drawHeight = this.scaleY == 1.0 ? available.getHeight() / this.scaleY : this.minimumDrawHeight;
        } else if (drawHeight > this.maximumDrawHeight) {
            drawHeight = this.maximumDrawHeight;
        }

        return new Rectangle2D.Double(0.0, 0.0, drawWidth, drawHeight);
    }

