	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		// Validate Java version
		if (!validateJavaVersion())
			return;

		// Parse command line arguments
		ParsedArgs parsedArgs = parseCommandLine(args);
		Log.init(true, parsedArgs.logLevel);

		// Handle connection to existing jEdit instance
		if (handleExistingInstance(parsedArgs))
			return;

		// Initialize settings directory
		Writer logWriter = initializeSettingsDirectory(parsedArgs);

		// Set up logging
		Log.setLogWriter(logWriter);
		Log.log(Log.NOTICE, jEdit.class, "jEdit version " + getVersion());
		Log.log(Log.MESSAGE, jEdit.class, "Settings directory is " + parsedArgs.settingsDirectory);

		// Initialize server
		EditServer server = initializeServer(parsedArgs);

		// Initialize core components
		initMisc();
		initSystemProperties();
		if (jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();
		initUserProperties();
		initPLAF();

		// Initialize Java 1.4 features if available
		if (OperatingSystem.hasJava14() && System.getProperty("jedit.nojava14") == null)
			initializeJava14Features();

		// Initialize actions, dockables, and VFS
		initActions();
		initDockables();
		GUIUtilities.advanceSplashProgress();
		VFSManager.init();

		// Load plugins if not disabled
		if (!parsedArgs.noPlugins)
			initPlugins();

		// Load history and recent files
		if (parsedArgs.settingsDirectory != null)
			loadHistoryAndRecentFiles(parsedArgs.settingsDirectory);

		GUIUtilities.advanceSplashProgress();

