		GUIUtilities.advanceSplashProgress();

		// Start plugins
		startPlugins();

		// Load macros and run startup scripts
		Macros.loadMacros();
		runStartupScripts(parsedArgs);

		// Run script specified with -run= parameter
		if (parsedArgs.scriptFile != null)
			runScript(parsedArgs.userDir, parsedArgs.scriptFile);

		// Properties changed notification
		propertiesChanged();
		GUIUtilities.advanceSplashProgress();

		// Open files from command line
		Buffer buffer = openFiles(null, parsedArgs.userDir, args);
