	//{{{ Private helper methods for main()

	/**
	 * Validates that the Java version meets the minimum requirement.
	 * @return true if Java version is valid, false otherwise
	 */
	private static boolean validateJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if (javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version " + javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			return false;
		}
		return true;
	}

	/**
	 * Parses command line arguments into a ParsedArgs object.
	 * @param args The command line arguments
	 * @return A ParsedArgs object containing parsed arguments
	 */
	private static ParsedArgs parseCommandLine(String[] args)
	{
		ParsedArgs parsedArgs = new ParsedArgs();

		// Parse log level
		if (args.length >= 1)
		{
			String levelStr = args[0];
			if (levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
			{
				parsedArgs.logLevel = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		// Parse other options
		boolean endOpts = false;
		parsedArgs.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"), ".jedit");
		parsedArgs.portFile = "server";
		parsedArgs.restore = true;
		parsedArgs.gui = true;
		parsedArgs.noPlugins = false;
		parsedArgs.noStartupScripts = false;
		parsedArgs.userDir = System.getProperty("user.dir");

		for (int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if (arg == null)
				continue;
			else if (arg.length() == 0)
				args[i] = null;
			else if (arg.startsWith("-") && !endOpts)
			{
				if (arg.equals("--"))
					endOpts = true;
				else if (arg.equals("-usage"))
				{
					version();
					System.err.println();
					usage();
					System.exit(1);
				}
				else if (arg.equals("-version"))
				{
					version();
					System.exit(1);
				}
				else if (arg.equals("-nosettings"))
					parsedArgs.settingsDirectory = null;
				else if (arg.startsWith("-settings="))
					parsedArgs.settingsDirectory = arg.substring(10);
				else if (arg.startsWith("-noserver"))
					parsedArgs.portFile = null;
				else if (arg.equals("-server"))
					parsedArgs.portFile = "server";
				else if (arg.startsWith("-server="))
					parsedArgs.portFile = arg.substring(8);
				else if (arg.startsWith("-background"))
					parsedArgs.background = true;
				else if (arg.equals("-nogui"))
					parsedArgs.gui = false;
				else if (arg.equals("-norestore"))
					parsedArgs.restore = false;
				else if (arg.equals("-noplugins"))
					parsedArgs.noPlugins = true;
				else if (arg.equals("-nostartupscripts"))
					parsedArgs.noStartupScripts = true;
				else if (arg.startsWith("-run="))
					parsedArgs.scriptFile = arg.substring(5);
				else
				{
					System.err.println("Unknown option: " + arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}

		// Construct full port file path
		if (parsedArgs.settingsDirectory != null && parsedArgs.portFile != null)
			parsedArgs.portFile = MiscUtilities.constructPath(
				parsedArgs.settingsDirectory, parsedArgs.portFile);
		else
			parsedArgs.portFile = null;

		return parsedArgs;
	}

	/**
	 * Handles connection to an existing jEdit instance if one exists.
	 * @param parsedArgs The parsed command line arguments
	 * @return true if connected to existing instance, false otherwise
	 */
	private static boolean handleExistingInstance(ParsedArgs parsedArgs)
	{
		if (parsedArgs.portFile == null || !new File(parsedArgs.portFile).exists())
			return false;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(parsedArgs.portFile));
			String check = in.readLine();
			if (!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"), port);
			DataOutputStream out = new DataOutputStream(socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(parsedArgs.restore, null, parsedArgs.scriptFile);
			out.writeUTF(script);
			out.close();

			System.exit(0);
			return true;
		}
		catch (Exception e)
		{
			Log.log(Log.NOTICE, jEdit.class, "An error occurred while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE, jEdit.class, "This probably means that jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE, jEdit.class, "the last time it was run.");
			Log.log(Log.NOTICE, jEdit.class, "If you don't know what this means, don't worry.");
			Log.log(Log.NOTICE, jEdit.class, e);
			return false;
		}
	}

	/**
	 * Initializes the settings directory and returns a log writer.
	 * @param parsedArgs The parsed command line arguments
	 * @return A Writer for the activity log, or null if logging is disabled
	 */
	private static Writer initializeSettingsDirectory(ParsedArgs parsedArgs)
	{
		if (parsedArgs.settingsDirectory == null)
			return null;

		File settingsDir = new File(parsedArgs.settingsDirectory);
		if (!settingsDir.exists())
			settingsDir.mkdirs();

		File macrosDir = new File(parsedArgs.settingsDirectory, "macros");
		if (!macrosDir.exists())
			macrosDir.mkdir();

		String logPath = MiscUtilities.constructPath(parsedArgs.settingsDirectory, "activity.log");
		backupSettingsFile(new File(logPath));

		try
		{
			return new BufferedWriter(new FileWriter(logPath));
		}
		catch (Exception e)
		{
			e.printStackTrace();
			return null;
		}
	}

	/**
	 * Initializes the EditServer based on command line arguments.
	 * @param parsedArgs The parsed command line arguments
	 * @return The initialized EditServer, or null if not needed
	 */
	private static EditServer initializeServer(ParsedArgs parsedArgs)
	{
		if (parsedArgs.portFile == null)
		{
			if (parsedArgs.background)
			{
				parsedArgs.background = false;
				System.err.println("You cannot specify both the -background and -noserver switches");
			}
			return null;
		}

		EditServer server = new EditServer(parsedArgs.portFile);
		if (!server.isOK())
			return null;

		return server;
	}

	/**
	 * Initializes Java 1.4 features if available.
	 */
	private static void initializeJava14Features()
	{
		try
		{
			ClassLoader loader = jEdit.class.getClassLoader();
			Class clazz;
			if (loader != null)
				clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
			else
				clazz = Class.forName("org.gjt.sp.jedit.Java14");

			java.lang.reflect.Method meth = clazz.getMethod("init", new Class[0]);
			meth.invoke(null, new Object[0]);
		}
		catch (Exception e)
		{
			Log.log(Log.ERROR, jEdit.class, e);
			System.exit(1);
		}
	}

