	 * @param settingsDirectory The settings directory path
	 */
	private static void loadHistoryAndRecentFiles(String settingsDirectory)
	{
		File history = new File(MiscUtilities.constructPath(settingsDirectory, "history"));
		if (history.exists())
			historyModTime = history.lastModified();
		HistoryModel.loadHistory(history);

		File recent = new File(MiscUtilities.constructPath(settingsDirectory, "recent.xml"));
		if (recent.exists())
			recentModTime = recent.lastModified();
		BufferHistory.load(recent);
	}

	/**
	 * Starts all loaded plugins.
	 */
	private static void startPlugins()
	{
		for (int i = 0; i < jars.size(); i++)
		{
			((EditPlugin.JAR) jars.elementAt(i)).getClassLoader().startAllPlugins();
		}
	}

	/**
	 * Runs startup scripts based on command line arguments.
	 * @param parsedArgs The parsed command line arguments
	 */
	private static void runStartupScripts(ParsedArgs parsedArgs)
	{
		if (parsedArgs.noStartupScripts)
			return;

		// Run site startup scripts
		if (jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome, "startup");
			File file = new File(path);
			if (file.exists())
				runStartupScripts(file);
		}

		// Run user startup scripts
		if (parsedArgs.settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(parsedArgs.settingsDirectory, "startup");
			File file = new File(path);
			if (!file.exists())
				file.mkdirs();
			else
				runStartupScripts(file);
		}
	}

	/**
	 * Runs a BeanShell script.
	 * @param userDir The user directory
	 * @param scriptFile The script file path
	 */
	private static void runScript(String userDir, String scriptFile)
	{
		scriptFile = MiscUtilities.constructPath(userDir, scriptFile);
		BeanShell.runScript(null, scriptFile, null, false);
	}

	/**
	 * Creates the main view and hides the splash screen.
	 * @param buffer The buffer to open in the view
	 * @param splitConfig The split configuration
	 * @param gui Whether to show the GUI
	 */
	private static void createViewAndHideSplash(Buffer buffer, String splitConfig, boolean gui)
	{
		final Buffer _buffer = buffer;
		final String _splitConfig = splitConfig;
		final boolean _gui = gui;

		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable() {
			public void run()
			{
				EditBus.send(new EditorStarted(null));

				if (_gui)
				{
					View view;
					if (_buffer != null)
						view = newView(null, _buffer);
					else
						view = newView(null, _splitConfig);
				}

				// Start I/O threads
				VFSManager.start();

				// Start edit server
				if (server != null)
					server.start();

				GUIUtilities.hideSplashScreen();

				Log.log(Log.MESSAGE, jEdit.class, "Startup complete");

				// Report any plugin errors
				if (pluginErrors != null)
				{
					String caption = jEdit.getProperty(
						"plugin-error.caption" + (pluginErrors.size() == 1 ? "-1" : ""),
						new Integer[] { new Integer(pluginErrors.size()) });

					new ErrorListDialog(
						jEdit.getFirstView(),
						jEdit.getProperty("plugin-error.title"),
						caption, pluginErrors, true);
					pluginErrors.removeAllElements();
				}

				// Ensure AWT toolkit is initialized
				Toolkit.getDefaultToolkit();
			}
		});
	}

