 * @return A deep copy of the supplier, or {@code null} if the source is
 *         {@code null}.
 */
private DrawingSupplier copyDrawingSupplier(DrawingSupplier supplier) {
    if (supplier == null) {
        return null;
    }
    if (supplier instanceof PublicCloneable) {
        PublicCloneable pc = (PublicCloneable) supplier;
        try {
            return (DrawingSupplier) pc.clone();
