    clone.dateFormatOverride = copyDateFormat(this.dateFormatOverride);
    clone.tickMarkPosition = this.tickMarkPosition;
    clone.timeZone = this.timeZone;
    clone.locale = this.locale;
    clone.timeline = this.timeline;
}

/**
 * Creates a copy of the given date format, or returns {@code null} if the
 * input is {@code null}.
 *
 * @param format  the format to copy (<code>null</code> permitted).
 *
 * @return A copy of the format, or {@code null}.
 */
private DateFormat copyDateFormat(DateFormat format) throws CloneNotSupportedException {
    if (format == null) {
        return null;
    }
    return (DateFormat) format.clone();
}

