def _decodePointer(self, strio, visited, off):
    """
    Decode a DNS name compression pointer.

    @type strio: file
    @param strio: The stream from which to read the pointer.

    @type visited: set
    @param visited: Set of already-visited offsets to detect loops.

    @type off: int
    @param off: Original stream position to restore after decoding.

    @raise ValueError: If a compression loop is detected.

    @return: The new offset to seek to.
    """
    new_off = ((ord(readPrecisely(strio, 1)) & 63) << 8
               | ord(readPrecisely(strio, 1)))
    if new_off in visited:
        raise ValueError("Compression loop in encoded name")
    visited.add(new_off)
    return new_off

