def decode(self, strio, length=None):
    """
    Decode a byte string into this Name.

    @type strio: file
    @param strio: Bytes will be read from this file until the full Name
    is decoded.

    @raise EOFError: Raised when there are not enough bytes available
    from C{strio}.

    @raise ValueError: Raised when the name cannot be decoded (for example,
        because it contains a loop).
    """
    visited = set()
    self.name = b''
    off = 0
    while 1:
        l = ord(readPrecisely(strio, 1))
        if l == 0:
            if off > 0:
                strio.seek(off)
            return
        if (l >> 6) == 3:
            new_off = self._decodePointer(strio, visited, off)
            if off == 0:
                off = strio.tell()
            strio.seek(new_off)
            continue
        label = readPrecisely(strio, l)
        self._processLabel(label)

def _decodePointer(self, strio, visited, off):
    """
    Decode a DNS name compression pointer and handle loop detection.

    @type strio: file
    @param strio: The stream from which to read the pointer.

    @type visited: set
    @param visited: Set of already visited offsets for loop detection.

    @type off: int
    @param off: Current stream offset for potential seek restoration.

    @raise ValueError: Raised when a compression loop is detected.

    @return: The new offset to seek to.
    @rtype: int
    """
    new_off = ((ord(readPrecisely(strio, 1)) & 63) << 8
               | ord(readPrecisely(strio, 1)))
    if new_off in visited:
        raise ValueError("Compression loop in encoded name")
    visited.add(new_off)
    return new_off

def _processLabel(self, label):
    """
    Process a decoded DNS label and append it to the name.

    @type label: bytes
    @param label: A single DNS label read from the stream.
    """
    if self.name == b'':
        self.name = label
    else:
        self.name = self.name + b'.' + label

